begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,api,private,auth;
select no_plan();
\ir fixtures/final-result-readiness-setup.sql
select ok(not has_function_privilege('authenticated','api.svc_final_result_readiness_begin_v2(jsonb)','execute'),'manager cannot self-attest successful files and reader probes');
select ok(not has_function_privilege('anon','api.svc_final_result_readiness_describe_v2(uuid)','execute'),'anonymous caller cannot enumerate staging readiness');
select ok(not has_function_privilege('service_role','private.final_result_verification_context(uuid,text,uuid)','execute'),'private actor context is not service executable');
select ok(not has_table_privilege('service_role','private.final_result_release_readiness','insert'),'readiness has no raw insert path');
select is((select count(*) from pg_class where oid in ('private.final_result_release_verifications'::regclass,'private.final_result_release_artifact_proofs'::regclass,'private.final_result_release_readiness'::regclass) and relrowsecurity),3::bigint,'all evidence relations are RLS enabled');
select is(private.final_result_verification_context('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87930000-0000-4000-8000-000000000001'),
 (api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())->'data')-array['artifacts','nextArtifactCursor'],'service evidence binds the same live context as actor probe API');
set local role service_role;
select is(api.svc_final_result_readiness_describe_v2('87950000-0000-4000-8000-000000000001')->'data','null'::jsonb,'no verification seeded');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"extra":true}'))$q$,'22023','Invalid final Result readiness attempt','unknown fields cannot be silently ignored');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"targetHash":"eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"}'))$q$,'22023','Final Result readiness context mismatch','attempt binds admitted target');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"permissionHash":"eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"}'))$q$,'22023','Final Result readiness context mismatch','attempt binds live manager grant');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"actorId":"87930000-0000-4000-8000-000000000002"}'))$q$,'55000','Final Result verification context is no longer eligible','service cannot certify an ordinary user as manager');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header(jsonb_build_object('startedAt',clock_timestamp()-interval '2 hours')))$q$,'22023','Final Result file verification is stale or invalid','file work starts within explicit freshness window');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"startedAt":"infinity"}'))$q$,'22023','Final Result file verification is stale or invalid','infinite timestamps are not fresh evidence');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header(jsonb_build_object('candidateFilesVerifiedAt',clock_timestamp()+interval '1 minute')))$q$,'22023','Final Result file verification is stale or invalid','future observation is bounded');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"candidateFiles":[]}'))$q$,'22023','Final Result Candidate file coverage mismatch','both ZIPs and Candidate metadata are required');
select is(api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header())#>>'{data,reused}','false','first exact attempt registered');
select is(api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header())#>>'{data,reused}','true','lost begin ACK recovers exact original attempt');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"readerSha256":"eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee"}'))$q$,'23505','Final Result readiness attempt identity conflict','same verification identity cannot be repurposed');
select throws_ok($q$select api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001')$q$,'55000','Final Result readiness coverage is incomplete','Candidate files alone cannot seal readiness');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001','[]')$q$,'22023','Invalid bounded final Result readiness batch','empty batch rejected');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{files}','[]')))$q$,'22023','Final Result artifact file coverage mismatch','all query HDF5/index/manifest files required');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{probes}','[]')))$q$,'22023','Final Result probe coverage mismatch','selected artifact requires its exact runtime probes');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{probes,0,result,uuid}','"87920000-0000-4000-8000-000000000011"')))$q$,'22023','Final Result probe coverage mismatch','file-contained unselected Result cannot replace selected sample');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{probes,0,contentHash}',to_jsonb(repeat('e',64)))))$q$,'22023','Final Result reader probe binding mismatch','registered content identity must match');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{probes,0,readerSha256}',to_jsonb(repeat('e',64)))))$q$,'22023','Final Result reader probe binding mismatch','reader binary hash is exact');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{probes,0,startedAt}',to_jsonb(clock_timestamp()-interval '16 minutes'))))$q$,'22023','Final Result reader verification is stale or invalid','old successful probe cannot authorize readiness');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{probes,0,lciPageCount}','0')))$q$,'22023','Final Result probe count mismatch','missing LCI page is not successful qualification');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{probes,0,queryCount}','999')))$q$,'22023','Final Result probe count mismatch','overview and exact LCI/LCIA query coverage is checked');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(pg_temp.readiness_proofs()->0,jsonb_set(pg_temp.readiness_proofs()->1,'{files}','[]')))$q$,'22023','Final Result artifact file coverage mismatch','invalid later proof rolls back entire batch');
select is(api.svc_final_result_readiness_describe_v2('87950000-0000-4000-8000-000000000001')#>>'{data,registeredArtifactCount}','0','failed batch leaves no first artifact behind');
select is(api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(pg_temp.readiness_proofs()->0))#>>'{data,insertedArtifactCount}','1','one exact artifact staged');
select throws_ok($q$select api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001')$q$,'55000','Final Result readiness coverage is incomplete','partial selected-artifact coverage cannot seal');
select is(api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',pg_temp.readiness_proofs())#>>'{data,insertedArtifactCount}','1','retry reuses first exact proof and appends missing second artifact');
select is(api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',pg_temp.readiness_proofs())#>>'{data,insertedArtifactCount}','0','complete replay inserts nothing');
select throws_ok($q$select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_set(pg_temp.readiness_proofs()->0,'{probes,0,observationsSha256}',to_jsonb(repeat('e',64)))))$q$,'23505','Final Result artifact proof identity conflict','same attempt cannot replace earlier observations');
select is(api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001')#>>'{data,artifactCount}','2','seal covers all selected artifacts');
select is(api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001')#>>'{data,probeCount}','2','seal covers exact deduplicated first/last probes');
select is(api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001')#>>'{data,fileCount}','14','seal covers four Candidate files and both complete query sets');
select is(api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001')->'data',api.svc_final_result_readiness_describe_v2('87950000-0000-4000-8000-000000000001')#>'{data,readinessReceipt}','lost seal ACK recovers original receipt without changing times');
select is(api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001')#>>'{data,publicationAuthorized}','false','stored readiness does not grant publication');
reset role;
select ok((select expires_at>clock_timestamp() and expires_at<=clock_timestamp()+interval '15 minutes' from private.final_result_release_readiness),'expiry uses oldest probe start, not completion or retry time');
select is((select status from private.lca_release_runs where id='87930000-0000-4000-8000-000000000010'),'prepared','readiness storage does not advance actor state');
select is((select count(*) from private.lca_release_publications),0::bigint,'readiness storage cannot publish');
select throws_ok($q$update private.final_result_release_artifact_proofs set proof='{}'$q$,'55000','Result query evidence is immutable','artifact observations cannot be rewritten');
select throws_ok($q$delete from private.final_result_release_readiness$q$,'55000','Result query evidence is immutable','sealed receipt cannot be erased');
set local role service_role;
select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"verificationId":"87950000-0000-4000-8000-000000000002"}'));
select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000002',pg_temp.readiness_proofs());
select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header(jsonb_build_object('verificationId','87950000-0000-4000-8000-000000000003','startedAt',clock_timestamp()-interval '1 hour'+interval '1 second')));
select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000003',pg_temp.readiness_proofs());
select pg_sleep(1.1);
select throws_ok($q$select api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000003')$q$,'55000','Final Result readiness evidence expired','file freshness expires during verification rather than extending at seal');
select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000002','87940000-0000-4000-8000-000000000001',repeat('d',64),repeat('c',64),false,'disable after synthetic verification');
select is(api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001')#>>'{data,runtimeRevision}','87940000-0000-4000-8000-000000000001','historical retry remains original evidence, never fresh runtime admission');
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"verificationId":"87950000-0000-4000-8000-000000000004"}'))$q$,'55000','Final Result verification context is no longer eligible','new readiness cannot use disabled runtime');
select throws_ok($q$select api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000002')$q$,'55000','Final Result verification context is no longer eligible','runtime disabled after all probes prevents a new seal');
select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000003','87940000-0000-4000-8000-000000000002',repeat('d',64),repeat('c',64),true,'re-enable same binary with new revision');
select throws_ok($q$select api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000002')$q$,'55000','Final Result verification context changed','same binary in a later admission cannot revive old probes');
reset role;
delete from private.roles where user_id='87930000-0000-4000-8000-000000000001' and team_id='00000000-0000-0000-0000-000000000000';
set local role service_role;
select throws_ok($q$select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"verificationId":"87950000-0000-4000-8000-000000000004","runtimeRevision":"87940000-0000-4000-8000-000000000003"}'))$q$,'55000','Final Result verification context is no longer eligible','revoked manager cannot establish a fresh verifier attempt');
reset role;
select is((select count(*) from private.final_result_release_readiness),1::bigint,'runtime drift never creates another readiness receipt');
select * from finish();
rollback;
